#include <stdio.h>

int main() {
    int n;
    /* 题目保证 n <= 100，所以开 100 个元素的数组就够用。
       数组长度必须是编译期常量，写成 int a[n] 有些环境编译不过 */
    int a[100];

    scanf("%d", &n);

    /* 读入：a[i] 本身是变量，所以同样要写取地址符 & */
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    /* 正序输出：第一个数前面不加空格，后面的数前面加一个空格 */
    for (int i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", a[i]);
    }
    printf("\n");

    /* 逆序输出：从下标 n-1 走到 0。
       循环条件是 i >= 0，写成 i > 0 会漏掉第一个元素 a[0] */
    for (int i = n - 1; i >= 0; i--) {
        if (i < n - 1) {
            printf(" ");
        }
        printf("%d", a[i]);
    }
    printf("\n");

    return 0;
}

