#include <stdio.h>

int main() {
    int n;
    int a[100];

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    /* 累加器必须先初始化为 0。
       局部变量不初始化时里面是内存里的随机值，累加结果会完全错掉 */
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
    }

    /* sum / n 是两个整数相除，结果只保留整数部分；
       乘 1.0 让整个表达式变成浮点运算，小数才不会丢 */
    double avg = sum * 1.0 / n;

    printf("%d\n", sum);
    printf("%.2f\n", avg);
    return 0;
}

tutorial.body:
把一组数加起来，不需要记住每一个数，只需要一个「累加器」：

int sum = 0;
for (int i = 0; i < n; i++) {
    sum += a[i];
}

sum += a[i] 是 sum = sum + a[i] 的简写。每一轮把当前元素加进总和。

这里最容易踩的坑是忘记初始化 sum = 0。C 里的局部变量不会自动清零，int sum; 后面直接 sum += a[i] 等于在一个随机的垃圾值上累加，结果是不可预测的（有时看着「差不多对」，有时是几千万）。

所以养成习惯：只要写累加器，先给它赋 0。

