#include <stdio.h>

int main() {
    int n;
    int a[100];

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    /* 关键一步：把最值初始化成第一个元素 a[0]，而不是 0。
       如果写 int max = 0，遇到「全是负数」的数组会输出错误的 0 */
    int max = a[0], min = a[0];
    int maxPos = 1, minPos = 1;

    /* 从下标 1 开始比，因为下标 0 已经作为初始值了 */
    for (int i = 1; i < n; i++) {
        /* 用 > 而不是 >=：相等的时候不更新位置，
           这样记录下来的就是「第一次出现」的位置 */
        if (a[i] > max) {
            max = a[i];
            maxPos = i + 1;   /* 下标从 0 开始，位置从 1 开始，所以要 +1 */
        }
        if (a[i] < min) {
            min = a[i];
            minPos = i + 1;
        }
    }

    printf("%d\n%d\n%d\n%d\n", max, maxPos, min, minPos);
    return 0;
}

