#include <stdio.h>

int main() {
    int n;
    int a[100];

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    /* 读入要查找的数 x。注意它不属于数组，单独声明 */
    int x;
    scanf("%d", &x);

    int count = 0;
    int first = -1;   /* -1 表示「还没有找到过」 */

    for (int i = 0; i < n; i++) {
        if (a[i] == x) {
            /* 只在第一次找到时记录位置，后面的出现不能覆盖它。
               如果这里不判断，first 最后会变成「最后一次出现」的位置 */
            if (first == -1) {
                first = i + 1;
            }
            count++;
        }
    }

    /* count > 0 就说明出现过，不用再单独记一个布尔标志 */
    printf("%s\n", count > 0 ? "yes" : "no");
    printf("%d\n", count);
    printf("%d\n", first);
    return 0;
}

