#include <stdio.h>

int main() {
    int r, c;
    /* 二维数组：a[行][列]，两个维度都要给常量大小。
       题目保证 r、c 不超过 50，所以开 50x50 */
    int a[50][50];

    scanf("%d %d", &r, &c);

    /* 读入：外层循环走行，内层循环走列，别把 r 和 c 写反 */
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            scanf("%d", &a[i][j]);
        }
    }

    /* 转置：不必真的搬动数据，输出时把两个下标对调就行。
       外层循环的次数变成了 c（转置后有 c 行），内层是 r */
    for (int i = 0; i < c; i++) {
        for (int j = 0; j < r; j++) {
            if (j > 0) {
                printf(" ");
            }
            printf("%d", a[j][i]);   /* 是 a[j][i]，不是 a[i][j] */
        }
        printf("\n");
    }

    return 0;
}

