#include <stdio.h>

int main() {
    int n;
    int a[100];

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    /* 冒泡排序：每一趟从头比较相邻两个数，把当前最大的数推到末尾。
       一共最多需要 n-1 趟（n 个数里前 n-1 个就位后，剩下的自然最小） */
    for (int i = 0; i < n - 1; i++) {
        /* 第 i 趟时，末尾已经有 i 个数排好了，所以只要比到 n-1-i。
           内层写成 j < n - 1 - i，是因为要访问 a[j+1]，下标最大到 n-1 */
        for (int j = 0; j < n - 1 - i; j++) {
            if (a[j] > a[j + 1]) {
                /* 借助临时变量交换两个元素，三步顺序不能颠倒 */
                int tmp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = tmp;
            }
        }
    }

    /* 输出：空格分隔，行末不加多余空格 */
    for (int i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", a[i]);
    }
    printf("\n");

    return 0;
}

